import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Search,
  AlertTriangle,
  FileText,
  Eye,
  Download,
  RefreshCw,
  Filter,
  ChevronDown,
} from 'lucide-react';

const API_BASE = import.meta.env.VITE_API_BASE_URL || 'http://localhost:3001';

const ReportHistory = () => {
  const navigate = useNavigate();
  
  // State
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('All Status');
  const [typeFilter, setTypeFilter] = useState('All Types');
  const [sortBy, setSortBy] = useState('Newest First');
  const [showFilters, setShowFilters] = useState(false);
  const [reports, setReports] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Load reports from backend (simple read-only)
  const loadReports = async () => {
    try {
      setLoading(true);
      setError(null);

      const userEmail = localStorage.getItem('userEmail') || 
                       sessionStorage.getItem('userEmail') || 
                       window.currentUserEmail;

      if (!userEmail) {
        throw new Error('User email not found');
      }

      const response = await fetch(`${API_BASE}/api/report-history`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
          'x-user-email': userEmail,
        },
      });

      if (!response.ok) {
        throw new Error(`Failed to load reports: ${response.status}`);
      }

      const data = await response.json();
      setReports(data.reports || []);
      
      console.log('📊 Loaded reports:', data.reports?.length || 0);
    } catch (err) {
      console.error('❌ Error loading reports:', err);
      setError(err.message);
      setReports([]);
    } finally {
      setLoading(false);
    }
  };

  // Load reports on mount and set up periodic refresh
  useEffect(() => {
    loadReports();
    
    // Refresh every 10 seconds to get latest status
    const refreshInterval = setInterval(loadReports, 10000);
    
    // Make refresh function available globally
    window.refreshReportHistory = loadReports;
    
    // Listen for events from other components
    const handleReportGenerated = () => {
      console.log('🔄 Report generated event received, refreshing...');
      setTimeout(loadReports, 1000);
    };
    
    window.addEventListener('reportGenerated', handleReportGenerated);
    window.addEventListener('focus', loadReports);
    
    return () => {
      clearInterval(refreshInterval);
      delete window.refreshReportHistory;
      window.removeEventListener('reportGenerated', handleReportGenerated);
      window.removeEventListener('focus', loadReports);
    };
  }, []);

  // Filter and sort reports
  const filteredReports = reports
    .filter(report => {
      const matchesSearch = !searchQuery || 
        report.caseId.toLowerCase().includes(searchQuery.toLowerCase()) ||
        report.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        report.type.toLowerCase().includes(searchQuery.toLowerCase());
      
      const matchesStatus = statusFilter === 'All Status' || report.status === statusFilter;
      const matchesType = typeFilter === 'All Types' || report.type === typeFilter;
      
      return matchesSearch && matchesStatus && matchesType;
    })
    .sort((a, b) => {
      const dateA = new Date(a.createdDate);
      const dateB = new Date(b.createdDate);
      return sortBy === 'Newest First' ? dateB - dateA : dateA - dateB;
    });

  // Action handlers
  const handleViewReport = (report) => {
    if (report.status === 'Processing') {
      // Go to MCP progress page to see live progress
      localStorage.setItem('mcp_case_id', report.caseId);
      navigate('/mcp-progress');
      return;
    }
    
    if (report.status === 'Generated' && report.s3Url) {
      // Open PDF directly
      window.open(report.s3Url, '_blank');
    }
    
    if (report.status === 'Failed') {
      // Go to MCP progress page to see error details
      localStorage.setItem('mcp_case_id', report.caseId);
      navigate('/mcp-progress');
    }
  };

  const handleDownloadReport = (report) => {
    if (!report.s3Url) return;
    
    const link = document.createElement('a');
    link.href = report.s3Url;
    link.download = `${report.caseId}-report.pdf`;
    link.click();
  };

  const handleRetry = (report) => {
    // Go back to MCP generation page
    localStorage.setItem('mcp_case_id', report.caseId);
    navigate('/medicalcostprojection');
  };

  // Status badge component
  const StatusBadge = ({ status, progress }) => {
    if (status === 'Generated') {
      return (
        <span className="px-3 py-1 text-xs font-semibold rounded-full bg-green-100 text-green-700">
          ✅ Completed
        </span>
      );
    }
    
    if (status === 'Processing') {
      return (
        <span className="px-3 py-1 text-xs font-semibold rounded-full bg-blue-100 text-blue-700 flex items-center gap-2">
          <span className="w-3 h-3 border-2 border-blue-600 border-t-transparent rounded-full animate-spin" />
          Processing {progress ? `(${progress}%)` : ''}
        </span>
      );
    }
    
    if (status === 'Failed') {
      return (
        <span className="px-3 py-1 text-xs font-semibold rounded-full bg-red-100 text-red-700">
          ❌ Failed
        </span>
      );
    }

    return (
      <span className="px-3 py-1 text-xs font-semibold rounded-full bg-yellow-100 text-yellow-700">
        ⏳ Pending
      </span>
    );
  };

  // Action buttons component
  const ActionButtons = ({ report }) => {
    if (report.status === 'Processing') {
      return (
        <button
          onClick={() => handleViewReport(report)}
          className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700"
        >
          View Progress
        </button>
      );
    }
    
    if (report.status === 'Generated') {
      return (
        <div className="flex gap-2">
          <button
            onClick={() => handleViewReport(report)}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 flex items-center gap-2"
          >
            <Eye size={16} />
            View PDF
          </button>
          <button
            onClick={() => handleDownloadReport(report)}
            className="px-4 py-2 bg-gray-600 text-white rounded-lg text-sm font-medium hover:bg-gray-700 flex items-center gap-2"
          >
            <Download size={16} />
            Download
          </button>
        </div>
      );
    }
    
    if (report.status === 'Failed') {
      return (
        <div className="flex gap-2">
          <button
            onClick={() => handleViewReport(report)}
            className="px-3 py-2 bg-red-600 text-white rounded-lg text-sm font-medium hover:bg-red-700"
          >
            View Error
          </button>
          <button
            onClick={() => handleRetry(report)}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700"
          >
            Retry
          </button>
        </div>
      );
    }

    return (
      <button
        onClick={() => handleRetry(report)}
        className="px-4 py-2 bg-green-600 text-white rounded-lg text-sm font-medium hover:bg-green-700"
      >
        Generate Report
      </button>
    );
  };

  if (loading) {
    return (
      <div className="bg-white border border-slate-200 rounded-2xl shadow-sm">
        <div className="p-12 text-center">
          <div className="w-8 h-8 border-2 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto mb-4" />
          <p className="text-sm text-slate-600">Loading report history…</p>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white border border-slate-200 rounded-2xl shadow-sm">
      {/* Header */}
      <div className="px-6 py-4 border-b border-slate-200 flex justify-between items-center">
        <h3 className="text-lg font-bold flex items-center gap-2">
          <FileText className="w-5 h-5 text-blue-600" />
          Report History
        </h3>
        <div className="flex items-center gap-3">
          <button
            onClick={loadReports}
            disabled={loading}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 flex items-center gap-2 disabled:opacity-50"
          >
            <RefreshCw size={16} className={loading ? 'animate-spin' : ''} />
            Refresh
          </button>
          <button
            onClick={() => setShowFilters(!showFilters)}
            className="px-4 py-2 bg-slate-100 text-slate-700 rounded-lg text-sm font-medium hover:bg-slate-200 flex items-center gap-2"
          >
            <Filter size={16} />
            Filters
            <ChevronDown size={16} className={`transition-transform ${showFilters ? 'rotate-180' : ''}`} />
          </button>
        </div>
      </div>

      {error && (
        <div className="p-4 bg-red-50 text-red-700 flex items-center gap-2">
          <AlertTriangle size={16} />
          {error}
        </div>
      )}

      {/* Filters */}
      {showFilters && (
        <div className="p-6 border-b border-slate-200">
          <div className="relative mb-4">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search by Case ID, Title, or Type..."
              className="w-full pl-10 pr-4 py-3 border border-slate-300 rounded-lg bg-white text-slate-900 placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Status</label>
              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg bg-white text-slate-900 focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option>All Status</option>
                <option>Pending</option>
                <option>Processing</option>
                <option>Generated</option>
                <option>Failed</option>
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Type</label>
              <select
                value={typeFilter}
                onChange={(e) => setTypeFilter(e.target.value)}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg bg-white text-slate-900 focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option>All Types</option>
                <option>MCP</option>
                <option>LCP</option>
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Sort By</label>
              <select
                value={sortBy}
                onChange={(e) => setSortBy(e.target.value)}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg bg-white text-slate-900 focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option>Newest First</option>
                <option>Oldest First</option>
              </select>
            </div>
          </div>
        </div>
      )}

      {/* Table */}
      <div className="overflow-x-auto">
        <table className="w-full">
          <thead className="bg-slate-50 border-b">
            <tr>
              <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Case ID</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Title / Type</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Created</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Status</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Report Date</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Actions</th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-slate-200">
            {filteredReports.map((report, index) => (
              <tr key={index} className="hover:bg-slate-50">
                <td className="px-6 py-4 whitespace-nowrap font-mono text-blue-600 font-medium">
                  {report.caseId}
                </td>
                <td className="px-6 py-4">
                  <div className="font-medium text-slate-900">{report.title}</div>
                  <div className="text-xs text-slate-500">{report.type}</div>
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-900">
                  {report.createdDate}
                </td>
                <td className="px-6 py-4 whitespace-nowrap">
                  <StatusBadge status={report.status} progress={report.progress} />
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-900">
                  {report.reportDate || '-'}
                </td>
                <td className="px-6 py-4 whitespace-nowrap">
                  <ActionButtons report={report} />
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {filteredReports.length === 0 && (
        <div className="p-12 text-center text-slate-500">
          <FileText className="w-12 h-12 text-slate-400 mx-auto mb-4" />
          <h3 className="text-lg font-medium text-slate-900 mb-2">No reports found</h3>
          <p className="text-sm text-slate-600">
            {searchQuery || statusFilter !== 'All Status' || typeFilter !== 'All Types'
              ? 'Try adjusting your search or filter criteria.'
              : 'No reports generated yet.'}
          </p>
        </div>
      )}
    </div>
  );
};

export default ReportHistory;