import React from 'react';
import { 
  CheckCircleIcon,
  ShieldCheckIcon,
  UsersIcon,
  LockClosedIcon,
  BoltIcon,
} from '@heroicons/react/24/outline';

const Icon = ({ name, size = 5, className = '', ...props }) => {
  const iconMap = {
    checkCircle: CheckCircleIcon,
    shield: ShieldCheckIcon,
    users: UsersIcon,
    lock: LockClosedIcon,
    zap: BoltIcon,
  };

  const IconComponent = iconMap[name] || null;
  
  if (!IconComponent) return null;

  const sizeClasses = {
    4: 'h-4 w-4',
    5: 'h-5 w-5',
    6: 'h-6 w-6',
  };

  return (
    <IconComponent 
      className={`${sizeClasses[size] || sizeClasses[5]} ${className}`} 
      {...props} 
    />
  );
};

export default Icon;
